WITH cust_profit AS (SELECT c.c_customer_sk, c.c_customer_id, ARRAY_AGG(DISTINCT cc.cc_name) AS call_centers_used, SUM(cs.cs_net_profit) AS total_net_profit, SUM(cs.cs_net_paid) AS total_net_paid, CASE WHEN SUM(cs.cs_net_profit) >= 200000 THEN 'Platinum' WHEN SUM(cs.cs_net_profit) >= 100000 THEN 'Gold' WHEN SUM(cs.cs_net_profit) >= 50000 THEN 'Silver' ELSE 'Bronze' END AS profit_tier FROM catalog_sales cs JOIN customer c ON cs.cs_bill_customer_sk = c.c_customer_sk JOIN call_center cc ON cs.cs_call_center_sk = cc.cc_call_center_sk GROUP BY c.c_customer_sk, c.c_customer_id) SELECT c_customer_id AS customer_id, total_net_profit, total_net_paid, profit_tier, call_centers_used, DENSE_RANK() OVER (ORDER BY total_net_profit DESC) AS profit_rank FROM cust_profit ORDER BY profit_rank LIMIT 10
